function renderLocations() {
  const l = state.loc; const cfg = getCfg(l.dep, l.shelf); const tiles = []; const taken = db.items.filter(i => { const p = parseLoc(i.location); return p && p.dep === l.dep && p.shelf === l.shelf && p.side === l.side && p.level === l.level }); const used = new Map(taken.map(i => [parseLoc(i.location).pos, i])); for (let p = 1; p <= cfg.positions; p++) { const i = used.get(p); tiles.push(`<div class="loc-tile ${i ? 'taken' : ''}" title="${esc(i ? i.code + ' — ' + i.name : 'Posição livre')}"><div class="num">Po${p}</div><small>${i ? esc(i.code) : 'Livre'}</small></div>`) } return `${heading('Estrutura física', 'Configuração de prateleiras', 'Cada prateleira pode ter sua própria quantidade de andares e posições. O andar pertence à prateleira selecionada.', roleIs('ADMIN', 'OPERADOR') ? `<button class="btn btn-primary" data-act="new-item-here">+ Cadastrar neste local</button>` : '')}
<div class="two-col"><section class="card card-pad"><h3 class="section-title">Estrutura da prateleira</h3><p class="section-sub">Defina o depósito e a prateleira e ajuste sua capacidade física.</p><div class="fields" style="margin-top:14px"><div class="field"><label>Depósito</label><input id="mapDep" type="number" min="1" max="99" value="${l.dep}"></div><div class="field"><label>Prateleira</label><input id="mapShelf" type="number" min="1" max="99" value="${l.shelf}"></div><div class="field"><label>Lado</label><select id="mapSide"><option value="A" ${l.side === 'A' ? 'selected' : ''}>Lado A</option><option value="B" ${l.side === 'B' ? 'selected' : ''}>Lado B</option></select></div><div class="field"><label>Andar em visualização</label><select id="mapLevel">${Array.from({ length: cfg.levels }, (_, i) => `<option value="${i + 1}" ${l.level === i + 1 ? 'selected' : ''}>Andar ${i + 1}</option>`).join('')}</select></div></div>${roleIs('ADMIN') ? `<div class="form-section"><h3>Capacidade desta prateleira</h3><div class="fields"><div class="field"><label>Quantidade de andares</label><input id="cfgLevels" type="number" min="1" max="30" value="${cfg.levels}"></div><div class="field"><label>Posições por andar</label><input id="cfgPositions" type="number" min="1" max="60" value="${cfg.positions}"></div></div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:14px"><button class="btn btn-primary" data-act="save-structure">Salvar estrutura</button><span class="pill blue">Próxima livre: ${nextFree(l.dep, l.shelf, l.side, Math.min(l.level, cfg.levels)) ? locCode(l.dep, l.shelf, l.side, Math.min(l.level, cfg.levels), nextFree(l.dep, l.shelf, l.side, Math.min(l.level, cfg.levels))) : 'Sem vaga'}</span></div></div><div class="notice" style="margin-top:16px">Ao reduzir a quantidade de andares ou posições, verifique se já existem itens cadastrados fora do novo limite antes de salvar.</div>` : `<div class="notice" style="margin-top:16px">Estrutura definida pelo administrador: ${cfg.levels} andares e ${cfg.positions} posições por andar. Você pode consultar a ocupação, mas não alterar a capacidade.</div>`}</section>
<section class="card card-pad"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px"><div><h3 class="section-title">Mapa de ocupação</h3><p class="section-sub">${esc(shelfKey(l.dep, l.shelf))} · Lado ${esc(l.side)} · Andar ${esc(l.level)}</p></div><span class="pill blue">${taken.length} ocupadas</span></div><div class="localmap" style="margin-top:16px">${tiles.join('')}</div></section></div><p class="footer-note">O endereço gerado respeita a estrutura configurada. Se uma prateleira tiver 3 andares e 6 posições por andar, o sistema não permitirá cadastrar um item fora desses limites.</p>`;
}
