function familyModal(id = '') { if (!guarded(['ADMIN'])) return; const family = db.families.find(f => f.id === id); const body = `<form id="familyForm" data-edit="${esc(id)}"><div class="fields"><div class="field wide"><label>Nome da família *</label><input id="familyName" required maxlength="48" value="${esc(family?.name || '')}" placeholder="Ex.: Ferramentas, Pneumática, Automação"></div><div class="field"><label>Cor da identificação *</label><input id="familyColor" type="color" value="${esc(family?.color || '#F47730')}"></div><div class="field"><label>Visualização</label><div class="family-preview" id="familyPreview"></div></div></div></form>`; openModal(family ? 'Editar família' : 'Nova família', 'A cor será usada automaticamente no cadastro e na etiqueta dos materiais.', body, `<button class="btn btn-ghost" data-act="close">Cancelar</button><button class="btn btn-primary" form="familyForm" type="submit">${family ? 'Salvar alterações' : 'Adicionar família'}</button>`, true); updateFamilyPreview(); }
