  ctx.fillStyle = m.text; ctx.font = '900 48px Arial'; ctx.fillText('ALMOXARIFADO INTELIGENTE', 56, 89); ctx.font = '800 29px Arial'; const family = String(m.label).toUpperCase(); const familyWidth = ctx.measureText(family).width; ctx.fillText(family, 1542 - familyWidth, 89);
  ctx.strokeStyle = '#d4dde4'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(800, 174); ctx.lineTo(800, 595); ctx.moveTo(50, 605); ctx.lineTo(1550, 605); ctx.stroke(); ctx.fillStyle = '#384c5d'; ctx.font = '800 28px Arial'; ctx.fillText('MATERIAL / PRODUTO', 58, 217); ctx.fillText('ENDEREÇO / CÓDIGO DE POSIÇÃO', 835, 217);
  ctx.fillStyle = '#132c43'; ctx.font = '900 68px Arial'; const nameLast = smartText(ctx, i.name.toUpperCase(), 58, 328, 685, 3, 68, 26); ctx.font = '900 68px Arial'; const addrLast = smartText(ctx, i.location, 835, 328, 690, 3, 68, 34);
  ctx.fillStyle = '#4e6475'; ctx.font = '500 28px Arial'; wrapText(ctx, i.details || 'Material cadastrado', 58, Math.max(nameLast + 50, 540), 675, 34, 1); ctx.font = '600 26px Arial'; ctx.fillText('Localização física para conferência', 835, Math.max(addrLast + 50, 540));
  ctx.fillStyle = '#385066'; ctx.font = '700 25px Arial'; ctx.fillText('CÓDIGO DO MATERIAL', 58, 667); ctx.fillText('SKU / REFERÊNCIA', 58, 762); ctx.fillText('MARCA', 460, 667); ctx.fillText('UNIDADE', 460, 762);
