function printLabel(id) { if (!guarded(['ADMIN', 'OPERADOR'])) return; const i = findItem(id); if (!i) return; $('#printMount').innerHTML = labelHtml(i, 'qrPrint'); window.paintQr(labelPayload(i), $('#qrPrint')); document.body.classList.add('printing'); setTimeout(() => window.print(), 120); }
