function exportJson() { if (!guarded(['ADMIN'])) return; const copy = JSON.parse(JSON.stringify(db)); delete copy.users; delete copy.userSeq; const blob = new Blob([JSON.stringify(copy, null, 2)], { type: 'application/json' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'almoxarifado_inteligente_backup_sem_credenciais.json'; a.click(); URL.revokeObjectURL(a.href); }

function importData(file) { if (!guarded(['ADMIN']) || !file) return; const fr = new FileReader(); fr.onload = () => { try { const parsed = JSON.parse(fr.result); if (!Array.isArray(parsed.items) || !Array.isArray(parsed.moves) || !Array.isArray(parsed.requests) || !parsed.seq) throw new Error('Formato inválido'); if (!confirm('Importar os dados e substituir materiais, pedidos e histórico? As contas atuais serão preservadas.')) return; parsed.users = db.users; parsed.userSeq = db.userSeq; db = parsed; if (!db.storage) db.storage = { defaults: { ...DEFAULT_CFG }, shelves: {} }; if (!db.storage.defaults) db.storage.defaults = { ...DEFAULT_CFG }; if (!db.storage.shelves) db.storage.shelves = {}; migrateFamilies(db); saveDb(); state.page = 'dashboard'; render(); toast('Dados importados; credenciais preservadas.'); } catch (e) { toast('Não foi possível importar o arquivo.', true) } }; fr.readAsText(file, 'utf-8'); }

