function attachInlineHandlers() { const mobile = $('#mobileNav'); if (mobile) mobile.onchange = e => { if (canPage(e.target.value)) { state.page = e.target.value; render(); } }; const q1 = $('#itemSearch'); if (q1) q1.addEventListener('input', e => { state.itemSearch = e.target.value; $('#itemsBody').innerHTML = itemRows(); }); const q2 = $('#moveSearch'); if (q2) q2.addEventListener('input', e => { state.moveSearch = e.target.value; const rows = db.moves.slice().reverse().filter(m => { const i = findItem(m.itemId); return !normalizeSearch(state.moveSearch) || matchesSearch([m.code, m.type, m.actor, m.reference, m.note, i?.name, i?.code], state.moveSearch) }); const body = $('#movesBody'); if (body) body.innerHTML = rows.length ? rows.map(m => { const i = findItem(m.itemId); const title = m.type === 'SAIDA' && m.receipt ? `<button class="btn btn-light btn-sm" data-act="receipt" data-id="${esc(m.id)}">Nota ${esc(m.receipt.number)}</button>` : m.type === 'SAIDA' ? '<span class="small muted">Registro anterior sem nota</span>' : ''; return `<tr><td><span class="code">${esc(m.code)}</span></td><td>${fmtDate(m.date)}</td><td><b>${esc(i?.name || 'Material')}</b><div class="small muted">${esc(i?.code || '')}</div></td><td>${esc(m.type)}</td><td>${m.type === 'REALOCACAO' ? '—' : (m.quantity > 0 ? '+' : '') + fmtN(m.quantity)}</td><td>${esc(m.actor)}</td><td>${esc(m.reference || '')}<div style="margin-top:6px">${title}</div></td></tr>` }).join('') : '<tr><td colspan="7" class="empty">Nenhuma movimentação encontrada.</td></tr>'; const count = $('#moveCount'); if (count) count.textContent = rows.length + ' movimentações'; }); const st = $('#itemStatus'); if (st) st.addEventListener('change', e => { state.statusFilter = e.target.value; $('#itemsBody').innerHTML = itemRows(); });['#mapDep', '#mapShelf', '#mapSide', '#mapLevel'].forEach(sel => { const el = $(sel); if (el) el.addEventListener('change', mapRead) }); const imp = $('#importFile'); if (imp) imp.addEventListener('change', e => importData(e.target.files[0])); }
document.addEventListener('click', async e => {
  const authButton = e.target.closest('[data-auth-mode]'); if (authButton) { authMode = authButton.dataset.authMode; renderGate(); return; } if (e.target?.id === 'startNfc') { const status = $('#nfcStatus'); if (!('NDEFReader' in window)) { if (status) status.textContent = 'NFC Web não suportado neste navegador/aparelho. Use a assinatura e a foto.'; return; } try { const reader = new NDEFReader(); await reader.scan(); reader.onreading = event => { const serial = event.serialNumber || 'Etiqueta NFC lida'; $('#nfcTag').value = serial; if (status) status.textContent = 'Etiqueta NFC lida: ' + serial; }; if (status) status.textContent = 'Aproxime uma etiqueta NFC.'; } catch (err) { if (status) status.textContent = 'Não foi possível iniciar NFC. Verifique HTTPS e permissões.'; } return; } const t = e.target.closest('[data-act]'); if (!t) { if (e.target.id === 'backdrop') closeModal(); return; } const a = t.dataset.act, id = t.dataset.id; if (a === 'logout') { logout(); return; } if (!activeUser()) { renderGate(); return; } if (a === 'my-account') { myAccountModal(); return; } if (a === 'self-password') { resetUserPasswordModal(activeUser().id, true); return; }
  if (a === 'nav') { if (canPage(id)) { state.page = id; render() } else toast('Página sem permissão.', true); return; }
  if (a === 'close') { closeModal(); return; }
  if (!access(a)) { toast('Seu perfil não permite esta operação.', true); return; }
  if (a === 'new-item') { itemModal(); return; } if (a === 'new-item-here') { itemModal('', state.loc); return; } if (a === 'edit-item') { itemModal(id); return; }
  if (a === 'new-family') { familyModal(); return; } if (a === 'edit-family') { familyModal(id); return; } if (a === 'delete-family') { deleteFamily(id); return; } if (a === 'toggle-inline-family') { const box = $('#quickFamilyEditor'); if (box) box.hidden = !box.hidden; return; } if (a === 'save-inline-family') { addFamilyInline(); return; }
  if (a === 'new-request') { requestModal(); return; } if (a === 'authorize') { authorizeModal(id); return; } if (a === 'reject') { rejectModal(id); return; } if (a === 'fulfill') { fulfillModal(id); return; }
  if (a === 'new-entry') { entryModal(); return; } if (a === 'new-adjust') { entryModal(true); return; }
  if (a === 'label') { labelModal(id); return; } if (a === 'download-label') { downloadLabel(id); return; } if (a === 'print-label') { printLabel(id); return; }
  if (a === 'export-report') { exportMovementReport(); return; } if (a === 'export-weekly') { exportMovementReport(7); return; } if (a === 'receipt') { showReceipt(id); return; } if (a === 'print-receipt') { printReceipt(id); return; }
  if (a === 'save-structure') { saveStructure(); return; } if (a === 'export') { exportJson(); return; } if (a === 'load-demo') { loadDemo(); return; }
  if (a === 'new-user') { userModal(); return; } if (a === 'edit-user') { userModal(id); return; } if (a === 'reset-pass') { const target = db.users.find(u => u.id === id); if (!target || !canManageUser(target)) return toast('Sua hierarquia não permite alterar esta senha.', true); resetUserPasswordModal(id, false); return; } if (a === 'delete-user') { deleteUser(id); return; }
  if (a === 'clear-db') { if (!roleIs('ADMIN')) return; if (confirm('Apagar materiais, movimentações e solicitações? As contas de usuário serão preservadas.') && confirm('Esta ação não pode ser desfeita sem backup. Confirmar?')) { const users = db.users, userSeq = db.userSeq; db = seed(); db.users = users; db.userSeq = userSeq; saveDb(); state.page = 'dashboard'; render(); toast('Dados operacionais apagados; contas mantidas.') } return; }
  if (a === 'cancel-request') { const r = db.requests.find(x => x.id === id); if (!r) return; const u = activeUser(); if (!(['SUPER_ADMIN', 'ADMIN'].includes(u.role) || (ALL_REQUEST_ROLES.includes(u.role) && r.requesterUserId === u.id))) return toast('Você não pode cancelar este pedido.', true); if (['PENDENTE', 'AUTORIZADA', 'PARCIAL'].includes(r.status) && confirm('Cancelar o saldo ainda não atendido da solicitação ' + r.code + '?')) { r.status = 'CANCELADA'; r.cancelledBy = u.name; r.cancelledAt = new Date().toISOString(); saveDb(); render(); toast('Restante do pedido cancelado.') } return; }
});
document.addEventListener('submit', e => { e.preventDefault(); const f = e.target; const id = f.id; if (id === 'setupForm' || id === 'loginForm' || id === 'registerForm') return; if (!activeUser()) return; if (id === 'userForm') { saveUser(f); return; } if (id === 'resetPasswordForm') { submitPasswordReset(f); return; } if (id === 'itemForm') return submitItem(f); if (id === 'familyForm') return saveFamily(f); if (id === 'requestForm') return submitRequest(); if (id === 'authorizeForm') return submitAuthorize(f); if (id === 'rejectForm') return submitReject(f); if (id === 'fulfillForm') return submitFulfill(f); if (id === 'entryForm') return submitMovement(false); if (id === 'adjustForm') return submitMovement(true); });
document.addEventListener('input', e => { if (['locDep', 'locShelf', 'locSide', 'locLevel', 'locPos', 'autoPos', 'itemName'].includes(e.target.id)) updateLocationPreview(); });
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); }); document.addEventListener('input', e => { if (['familyName', 'familyColor'].includes(e.target.id)) updateFamilyPreview(); });
$('#quickNew').addEventListener('click', () => { if (roleIs('ADMIN', 'OPERADOR')) itemModal(); else toast('Seu perfil não pode cadastrar materiais.', true) });
initSessionLock();
window.addEventListener('beforeunload', () => { const lock = JSON.parse(localStorage.getItem(LOGIN_LOCK_KEY) || 'null'); if (lock?.tabId === TAB_ID) localStorage.removeItem(LOGIN_LOCK_KEY); });
window.addEventListener('storage', e => { if (e.key !== LOGIN_LOCK_KEY || !sessionUserId) return; const lock = JSON.parse(e.newValue || 'null'); if (lock?.userId === sessionUserId && lock.tabId !== TAB_ID) { sessionUserId = ''; sessionStorage.removeItem(SESSION_KEY); renderGate(); toast('Esta conta foi aberta em outra aba. O acesso desta aba foi encerrado.', true); } });
function initSessionLock() { if (!sessionUserId) return; const old = JSON.parse(localStorage.getItem(LOGIN_LOCK_KEY) || 'null'); if (old && old.expires > Date.now() && old.userId === sessionUserId && old.tabId !== TAB_ID) { sessionUserId = ''; sessionStorage.removeItem(SESSION_KEY); return; } localStorage.setItem(LOGIN_LOCK_KEY, JSON.stringify({ userId: sessionUserId, tabId: TAB_ID, expires: Date.now() + 12 * 60 * 60 * 1000 })); }
async function submitLogin() { const login = normalizedLogin($('#authLogin').value), pass = $('#authPassword').value, u = db.users.find(x => x.login === login && !x.disabled); try { const match = u && (await hashPassword(pass, u.salt, u.hashAlgo || 'pbkdf2-sha256')) === u.hash; if (!match) { toast('Login ou senha inválidos.', true); return; } const lock = JSON.parse(localStorage.getItem(LOGIN_LOCK_KEY) || 'null'); if (lock && lock.expires > Date.now() && lock.userId === u.id && lock.tabId !== TAB_ID) { toast('Esta conta já está conectada em outra aba deste navegador.', true); return; } localStorage.setItem(LOGIN_LOCK_KEY, JSON.stringify({ userId: u.id, tabId: TAB_ID, expires: Date.now() + 12 * 60 * 60 * 1000 })); sessionUserId = u.id; sessionStorage.setItem(SESSION_KEY, sessionUserId); state.page = 'dashboard'; renderGate(); toast('Bem-vindo, ' + u.name + '.'); } catch (e) { toast('Não foi possível verificar a senha.', true) } }
function logout() { const lock = JSON.parse(localStorage.getItem(LOGIN_LOCK_KEY) || 'null'); if (lock?.tabId === TAB_ID) localStorage.removeItem(LOGIN_LOCK_KEY); sessionUserId = ''; sessionStorage.removeItem(SESSION_KEY); closeModal(); renderGate(); }
renderGate();

function fileToDataUrl(file) { return new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(String(fr.result)); fr.onerror = reject; fr.readAsDataURL(file); }); }
function turnoverLevel(item) { const since = Date.now() - 90 * 86400000; const qty = db.moves.filter(m => m.itemId === item.id && m.type === 'SAIDA' && new Date(m.date).getTime() >= since).reduce((a, m) => a + Math.abs(Number(m.quantity) || 0), 0); const avg = qty / 90; return avg >= 0.5 ? { label: 'Alta', value: 3 } : avg >= 0.1 ? { label: 'Média', value: 2 } : { label: 'Baixa', value: 1 }; }
function excelEscape(v) { return esc(v).replace(/\n/g, ' '); }
function exportMovementReport(days = null) { if (!guarded(['ADMIN'])) return; let start = $('#reportStart')?.value || '', end = $('#reportEnd')?.value || ''; if (days) { end = new Date().toISOString().slice(0, 10); start = new Date(Date.now() - (days - 1) * 86400000).toISOString().slice(0, 10); } if (start && end && start > end) return toast('A data inicial não pode ser posterior à final.', true); const filtered = db.moves.filter(m => { const d = String(m.date || '').slice(0, 10); return (!start || d >= start) && (!end || d <= end) }); const rows = filtered.map(m => { const i = findItem(m.itemId); return `<tr><td>${excelEscape(m.code)}</td><td>${excelEscape(fmtDate(m.date))}</td><td>${excelEscape(i?.code || m.itemId)}</td><td>${excelEscape(i?.name || '')}</td><td>${excelEscape(m.type)}</td><td>${excelEscape(m.withdrawalCategory || '')}</td><td>${excelEscape(m.quantity)}</td><td>${excelEscape(i?.unit || '')}</td><td>${excelEscape(m.actor)}</td><td>${excelEscape(m.reference)}</td><td>${excelEscape(m.invoiceNumber || '')}</td><td>${excelEscape(m.receiverSignature || '')}</td></tr>` }).join(''); const table = `<html><head><meta charset="utf-8"></head><body><table border="1"><thead><tr><th>Código</th><th>Data</th><th>Código material</th><th>Material</th><th>Operação</th><th>Categoria retirada</th><th>Quantidade</th><th>Unidade</th><th>Responsável</th><th>Referência</th><th>Nota fiscal</th><th>Recebedor</th></tr></thead><tbody>${rows}</tbody></table></body></html>`; const blob = new Blob(['\ufeff', table], { type: 'application/vnd.ms-excel;charset=utf-8' }), url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = `relatorio_almoxarifado_${start || 'inicio'}_${end || 'hoje'}.xls`; a.click(); URL.revokeObjectURL(url); toast('Relatório Excel gerado com ' + filtered.length + ' movimentações.'); }
function saveWeeklySnapshot() { const monday = new Date(); monday.setHours(0, 0, 0, 0); monday.setDate(monday.getDate() - ((monday.getDay() + 6) % 7)); const week = monday.toISOString().slice(0, 10); if (db.weeklyReports.some(x => x.week === week)) return; const from = new Date(Date.now() - 7 * 86400000).toISOString(); db.weeklyReports.push({ week, createdAt: new Date().toISOString(), moves: db.moves.filter(m => m.date >= from).length, items: db.items.length, low: db.items.filter(i => Number(i.stock) <= Number(i.min)).length }); if (db.weeklyReports.length > 60) db.weeklyReports = db.weeklyReports.slice(-60); saveDb(); }
